const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = Number(input[0]);
let minPrice = Infinity;

for (let i = 1; i <= n; i++) {
  const price = Number(input[i * 2 - 1]);
  const grams = Number(input[i * 2]);
  minPrice = Math.min(minPrice, price * 1000 / grams);
}

console.log(minPrice.toFixed(2));
